select
    id,code_sn,ingredients_id,ingredients_name,manufacturer_id,manufacturer_name,part_number,lot_number,product_id,product_name,item_specification,net_weight,gross_weight,tare_weight,measure_id,measure_name,job_number,status,is_deleted,version,create_by,create_time,update_by,update_time,attr1,attr2,attr3,item_id
from wms_ingredients_log

    is_deleted = 0
     and id = #{id}
     and code_sn = #{codeSn}
     and ingredients_id = #{ingredientsId}
     and ingredients_name = #{ingredientsName}
     and manufacturer_id = #{manufacturerId}
     and manufacturer_name = #{manufacturerName}
     and part_number = #{partNumber}
     and lot_number = #{lotNumber}
     and product_id = #{productId}
     and product_name = #{productName}
     and item_specification = #{itemSpecification}
     and net_weight = #{netWeight}
     and gross_weight = #{grossWeight}
     and tare_weight = #{tareWeight}
     and measure_id = #{measureId}
     and measure_name = #{measureName}
     and job_number = #{jobNumber}
     and status = #{status}
     and is_deleted = #{isDeleted}
     and version = #{version}
     and create_by = #{createBy}
     and create_time = #{createTime}
     and update_by = #{updateBy}
     and update_time = #{updateTime}
     and attr1 = #{attr1}
     and attr2 = #{attr2}
     and attr3 = #{attr3}
     and item_id = #{itemId}

        AND date_format(create_time,'%y%m%d') >= date_format(#{params.beginTime},'%y%m%d')


        AND date_format(create_time,'%y%m%d') <= date_format(#{params.endTime},'%y%m%d')


    ${params.dataScope}

order by create_time desc

